UPDATE posts SET body='حين تختار لجنة المكتبة الكتب بناءً على اقتراحات روّادها، فإنها تتعلم الكثير عن الذين يقرؤون بالفعل. أما الطفل الذي لم يدخل المكتبة قط، والأم التي لا يناسبها موعد الفتح، فلا يصل صوتهما إلى صندوق الاقتراحات. هنا يصبح اختيار الكتب سؤالًا عن صاحب الحق في تعريف احتياجات الحي المعرفية.

لنجرب تخصيص جزء من ميزانية الاقتناء لترشيحات تُجمع في المدرسة والسوق ومواقف النقل. وبعد شهرين نسأل من اقترحوا الكتب إن كانوا قد استعاروها، ونستمع خصوصًا إلى من تعذّر عليهم الحضور. قد تكون ساعة فتح إضافية أثمن للحي من رف جديد.

لو كانت لك كلمة في ميزانية المكتبة، فأي معلومة عن الغائبين تحتاج إليها قبل أن تشتري الكتاب التالي؟'
WHERE author_id=(SELECT id FROM users WHERE email='editorial@example.invalid') AND title='مكتبة الحي التي يشارك الجميع في اختيار كتبها';

UPDATE posts SET body='قد تكسب قطعة أرض في وسط الحي أعلى الأصوات لإنشاء حديقة، بينما يفصلها عن أقرب مدرسة شارع يصعب عبوره. في خريطة التخطيط تبدو المسافة قصيرة. وفي يوم طفل يمشي أو كبير سن يتوقف ليستريح، تدخل في حساب المسافة أشياء أخرى، منها الظلّ، وزمن انتظار العبور، والمقعد الأخير قبل الوصول.

يمكن مقارنة موقعين عبر مشي الطريق مع مستخدمين مختلفين في ساعة الظهيرة، ثم تقدير كلفة تهيئة الوصول والري والصيانة لكل موقع. عندئذ يصبح من الممكن مناقشة المفاضلة علنًا؛ فقد يكلّف الموقع الأقرب إلى الأسر الأقل خدمةً أكثر في البداية، ويتيح لها استخدامًا يوميًا يدوم سنوات.

إذا اختلف تصويت السكان مع نتائج تجربة المشي، كيف توزّع وزن كل منهما في قرار الاختيار؟'
WHERE author_id=(SELECT id FROM users WHERE email='editorial@example.invalid') AND title='كيف نختار موقع حديقة مجتمعية؟';

UPDATE posts SET body='تخيّل برنامجًا لتدريب الشباب على التسعير. في الاستبانة الختامية عبّر المشاركون عن رضاهم، ثم زار الفريق أحدهم بعد شهر فوجده يبيع بالأسعار القديمة. شرح الشاب أنه صار يحسب تكلفة المنتج بدقة، لكنه يبيع بالدَّين لأسر يعرفها ويخشى أن يفقدها. كشفت الزيارة معرفة اكتسبها المتدرّب وقيدًا اقتصاديًا غاب عن تصميم التدريب.

تكتسب المتابعة قيمتها حين تتّسع لمثل هذه الإجابة. يمكن سؤال من أكمل البرنامج ومن انسحب منه عن آخر قرار اتخذه في عمله، وما الذي أثّر فيه، ثم عرض تفسير الفريق عليه ليصححه. وفي الدورة التالية يُخصّص الوقت للحالات التي احتار فيها المشاركون فعلًا.

ما الشهادة التي لو سمعتها من أحد المستفيدين لدفعتك إلى تغيير برنامج تُظهر لوحة مؤشراته أنه ناجح؟'
WHERE author_id=(SELECT id FROM users WHERE email='editorial@example.invalid') AND title='ماذا يخبرنا المستفيدون بعد انتهاء المبادرة؟';

INSERT INTO posts(author_id,topic,title,body) VALUES
((SELECT id FROM users WHERE email='editorial@example.invalid'),'المجتمع','من يملك قرار الوقف بعد تغيّر الحاجة؟','لنتصوّر وقفًا تعليميًا يوزّع دفاتر على طلاب قرية. بعد سنوات أصبحت الدفاتر متاحة، وبقيت كلفة الانتقال إلى المدرسة عائقًا أمام بعض الأسر. يعرف الناظر عدد الحقائب التي سلّمها بدقة، لكن هذا السجل وحده لا يخبره أيّ نفقة تُعين هؤلاء الطلاب على مواصلة الدراسة.

يمكن لمجلس الوقف أن يوثّق المقصد وشروط الواقف، ثم يستمع إلى الأسر والمدرسة ويعرض البدائل على الجهة المخوّلة بالنظر فيها. تستحق الدراسة هنا حالُ الطالب الذي انقطع؛ فهو يغيب عادةً عن قوائم التوزيع التي يعتمد عليها المجلس لمعرفة المستفيدين.

كيف تصمّم موعدًا دوريًا لمراجعة الحاجة، ومن تمنحه حق طرحها على جدول أعمال المجلس؟'),
((SELECT id FROM users WHERE email='editorial@example.invalid'),'الاقتصاد','فاتورة المورد الصغير وكلفة الانتظار','قد تتساوى قيمة عقدين ويختلف أثرهما في اقتصاد الحي. فالورشة التي تدفع أجور عمّالها أسبوعيًا وتقبض مستحقاتها بعد ثلاثة أشهر تموّل المشروع من سيولتها. وربما تعتذر عن المناقصة التالية رغم جودة عملها. إذا اكتفت الجهة المشترية بمقارنة سعر القطعة، فلن ترى الكلفة التي تحمّلها المورد كي تستطيع هي تأجيل الدفع.

يمكن تجربة دفعات مرتبطة بتسليمات صغيرة، ثم مقارنة السعر والجودة وعدد الموردين القادرين على العودة. ومن المفيد أن يُسأل أيضًا أصحاب الورش الذين اطّلعوا على المناقصة ولم يتقدموا إليها؛ فقرارهم يفسّر جانبًا مما غاب عن جدول العروض.

أي بند ستراجعه أولًا إذا أردت أن تتّسع المنافسة وأن تحتفظ الجهة المشترية بحقها في التحقق من جودة التسليم؟'),
((SELECT id FROM users WHERE email='editorial@example.invalid'),'البيئة','من يتكفّل بظلّ الشجرة الخامسة؟','لنتخيّل مدرستين تملكان الميزانية نفسها. تزرع الأولى عشرين شجرة في يوم تطوعي، وتزرع الثانية خمسًا وتحتفظ بمخصص للريّ في الإجازة. بعد صيفين يمكن أن يختلف نصيب الطلاب من الظل اختلافًا كبيرًا. لحظة الغرس تصلح للصورة، أما مصير الشجرة فيتقرر في أسابيع يقلّ فيها الحضور وتزداد حاجتها إلى الماء.

يمكن رسم مسار خروج الطلاب عند الظهيرة وتحديد النقطة التي ينتظرون عندها الحافلة، ثم اختيار النوع والموقع وإسناد مسؤولية الصيانة إلى جهة تملك وقتًا وميزانية. يصبح السؤال بعد ذلك قابلًا للملاحظة في الفناء نفسه؛ كم طالبًا يستطيع الانتظار في الظل، وكم يكلّف استمرار ذلك؟

إذا خُفّضت موازنة المبادرة إلى النصف، فأيّ الأشجار تُبقي، وأيّ التزامات الرعاية تصون؟'),
((SELECT id FROM users WHERE email='editorial@example.invalid'),'التعليم','حين يصبح وقت المعلّم جزءًا من ميزانية التقنية','قد تحصل مدرستان على المنصة الرقمية ذاتها. في إحداهما يُمنح المعلّم ساعة أسبوعية يراجع فيها إجابات طلابه مع زميل، وفي الأخرى تُضاف متابعة المنصة إلى آخر اليوم. يبدو الاستثمار متساويًا في فاتورة الترخيص، ويبدو مختلفًا حين نحسب الوقت الذي يحتاجه المعلّم ليغيّر درس الغد.

تجربة صغيرة قد تكشف هذه الفجوة. يختار فريق المادة خطأً شائعًا في فهم الكسور، ويصمّم نشاطًا قصيرًا لمعالجته، ثم يفحص حلّ الطلاب لمسألة جديدة. ويُسجَّل إلى جانب النتيجة الوقت الذي استغرقه إعداد النشاط وتصحيحه، حتى يستطيع الفريق تقدير إمكان تكراره.

ما الذي تطلب رؤيته قبل تجديد الترخيص لعام آخر، ومن يملك الوقت اللازم لجمع تلك المعلومة؟'),
((SELECT id FROM users WHERE email='editorial@example.invalid'),'الاقتصاد','متى ينتهي المشروع وتبقى القدرة؟','لنتخيّل تعاونية اشترت غرفة تبريد لصغار المزارعين بمنحة. في الموسم الأول انخفض التلف، ثم تعطّل الضاغط بعد انتهاء التمويل. تكشف لحظة العطل شيئًا يصعب قياسه يوم الافتتاح؛ هل يستطيع الأعضاء تشخيص المشكلة، والاتفاق على كلفة الإصلاح، وطلب قطعة الغيار في الوقت المناسب؟

يمكن اختبار هذه القدرة قبل خروج المموّل. يضع الأعضاء تسعيرة تغطي التشغيل واحتياطي الصيانة، ويجرّبونها في موسم يقلّ فيه المحصول. عندها يظهر سؤال توزيعي دقيق؛ هل تحرم الرسوم أصغر المنتجين من الخدمة التي أُنشئت لهم أصلًا؟ يمكن عرض أثر أكثر من تسعيرة على دخل أسر بعينها قبل التصويت.

أي قرار ينبغي أن يتخذه أعضاء التعاونية بأنفسهم خلال فترة المنحة حتى نثق بقدرتهم على إدارة الأصل بعدها؟');
